<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { Plus } from '@lucide/vue'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { notifyError } from '../../api.js'
import { ruleLabRead, ruleLabWrite } from '../../rulelab/api.js'
import { clockPolicies, countLabel, datasetPayload, initialPolicies, inputChart, qualityLabels, reasonText, ruleLabTime, semantics, stateLabel, stateTone } from '../../rulelab/helpers.js'
import TimeSeriesChart from '../ops/TimeSeriesChart.vue'
const props=defineProps({items:{type:Array,default:()=>[]},devices:{type:Array,default:()=>[]},deviceId:{type:String,default:''},selected:Object})
const emit=defineEmits(['refresh','select','navigate','open-experiments'])
const editable=computed(()=>can('menu:devices')&&can('POST /api/v1/rule-lab/datasets')),shareable=computed(()=>can('POST /api/v1/rule-lab/datasets/publish'))
const dialog=ref(false),saving=ref(false),error=ref(''),detail=ref(null),detailLoading=ref(false),detailError=ref(''),sample=ref([]),total=ref(0),pageRows=ref([]),page=ref(1),clock=ref('event'),property=ref(''),chartDevice=ref(''),inputDialog=ref(false),input=ref(null)
const form=reactive({scope:'personal',deviceIds:[],range:null,warmupStart:null,timeBasis:'EVENT',clockPolicy:'EVENT_AS_PROCESSING',semanticsVersion:Object.keys(semantics)[1],initialStatePolicy:'EMPTY_UNKNOWN',idempotencyKey:''})
let generation=0,disposed=false
const deviceName=id=>props.devices.find(row=>row.id===id)?.name||id
const properties=computed(()=>[...new Set(sample.value.filter(row=>!chartDevice.value||row.message.deviceId===chartDevice.value).flatMap(row=>Object.entries(row.message.properties||{}).filter(([,value])=>typeof value==='number'&&Number.isFinite(value)).map(([key])=>key)))].sort())
const chart=computed(()=>inputChart(sample.value,chartDevice.value,property.value,clock.value))
function create(){Object.assign(form,{scope:'personal',deviceIds:props.deviceId?[props.deviceId]:[],range:null,warmupStart:null,timeBasis:'EVENT',clockPolicy:'EVENT_AS_PROCESSING',semanticsVersion:Object.keys(semantics)[1],initialStatePolicy:'EMPTY_UNKNOWN',idempotencyKey:createClientId()});error.value='';dialog.value=true}
async function save(){if(saving.value)return;const token=generation;saving.value=true;error.value='';try{const row=await ruleLabWrite('datasets','','',datasetPayload(form,form.idempotencyKey));if(token!==generation||disposed)return;dialog.value=false;emit('select',row);emit('refresh')}catch(cause){if(token===generation&&!disposed){error.value=cause.message;notifyError(cause)}}finally{if(token===generation)saving.value=false}}
async function loadPage(){const id=detail.value?.id,token=generation;if(!id)return;try{const result=await ruleLabRead('datasets',id,'inputs',{limit:20,offset:(page.value-1)*20});if(token===generation&&!disposed){pageRows.value=result.items||[];total.value=result.total||0}}catch(cause){if(token===generation&&!disposed)detailError.value=cause.message}}
async function inspect(row){const token=++generation;detail.value=row;detailLoading.value=true;detailError.value='';sample.value=[];pageRows.value=[];total.value=0;page.value=1;inputDialog.value=false;property.value='';chartDevice.value=row.deviceIds[0]||'';try{const fresh=await ruleLabRead('datasets',row.id);if(token!==generation||disposed)return;detail.value=fresh;const samples=[];for(let offset=0;offset<500;offset+=100){const result=await ruleLabRead('datasets',row.id,'inputs',{limit:100,offset});if(token!==generation||disposed)return;samples.push(...(result.items||[]));total.value=result.total||0;if(!result.items?.length||samples.length>=total.value)break}sample.value=samples;property.value=properties.value[0]||'';await loadPage()}catch(cause){if(token===generation&&!disposed)detailError.value=cause.message}finally{if(token===generation)detailLoading.value=false}}
function raw(row){if(row.message.rawMessageId)emit('navigate','raw',{deviceId:row.message.deviceId,messageId:row.message.rawMessageId})}
watch(()=>[props.selected?.id,props.selected?.status],()=>{if(props.selected&&(detail.value?.id!==props.selected.id||detail.value?.status!==props.selected.status))inspect(props.selected)},{immediate:true})
onBeforeUnmount(()=>{disposed=true;generation++})
</script>
<template><section class="lab-stack"><div class="lab-toolbar"><p class="lab-hint">固定完整标准消息及来源版本，分别保存预热区间、排序、处理时钟与初态政策。</p><ui-button v-if="editable" type="primary" size="small" @click="create"><Plus/>新建固定数据集</ui-button></div><div class="lab-table-scroll"><ui-table :data="items" empty-text="暂无固定数据集。"><ui-table-column label="设备 / 数据集" min-width="210"><template #default="{row}">{{row.deviceIds.map(deviceName).join('、')}}<p class="lab-meta">{{ruleLabTime(row.start)}} 至 {{ruleLabTime(row.end)}}</p></template></ui-table-column><ui-table-column label="状态 / 输入" min-width="160"><template #default="{row}"><ui-tag :type="stateTone(row.status)">{{stateLabel(row.status)}}</ui-tag><p class="lab-meta">固定输入 {{countLabel(row.inputCount)}} 条</p></template></ui-table-column><ui-table-column label="时钟 / 初态" min-width="280"><template #default="{row}">{{clockPolicies[row.clockPolicy] || row.clockPolicy}}<p class="lab-meta">{{qualityLabels[row.reproductionQuality] || row.reproductionQuality}} · 初态 {{qualityLabels[row.initialStateQuality] || row.initialStateQuality}}</p></template></ui-table-column><ui-table-column label="操作" width="150"><template #default="{row}"><ui-button :data-lab-dataset="row.id" text size="small" @click="emit('select',row)">输入与覆盖</ui-button><ui-button v-if="['SUCCEEDED','PARTIAL'].includes(row.status)" text size="small" @click="emit('select',row);emit('open-experiments')">用于实验</ui-button></template></ui-table-column></ui-table></div>
 <template v-if="detail"><div class="lab-card lab-stack"><h3>固定数据集与来源</h3><p class="lab-meta">设备 {{detail.deviceIds.map(deviceName).join('、')}} · 固定事实 {{detail.factsHash || '尚未固定完成'}}</p><p class="lab-meta">主窗口 {{ruleLabTime(detail.start)}} 至 {{ruleLabTime(detail.end)}} · 预热起点 {{ruleLabTime(detail.warmupStart)}}</p><p>{{clockPolicies[detail.clockPolicy]}} · {{semantics[detail.semanticsVersion]}}<br>{{initialPolicies[detail.initialStatePolicy]}}</p><p class="lab-hint">重现质量 {{qualityLabels[detail.reproductionQuality] || detail.reproductionQuality}} · 初态 {{qualityLabels[detail.initialStateQuality] || detail.initialStateQuality}}</p><ui-alert v-for="reason in detail.limitations || []" :key="reason" :title="reasonText(reason)" type="warning" :closable="false"/><ui-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>来源 / 版本</th><th>覆盖</th><th>读取时点</th><th>限制</th></tr></thead><tbody><tr v-for="source in detail.coverage || []" :key="source.source+source.start"><td>{{source.source}}<p>{{source.version}}</p></td><td>{{ruleLabTime(source.start)}} 至 {{ruleLabTime(source.end)}}</td><td>{{ruleLabTime(source.readAt)}}</td><td>{{source.complete?'已覆盖':'部分或未知'}} {{reasonText(source.reason)}}</td></tr></tbody></table></div></div><ui-skeleton v-if="detailLoading" :rows="4"/><template v-else><div class="lab-card lab-stack"><h3>固定输入字段曲线</h3><div class="lab-filter-row"><ui-select v-model="chartDevice" @change="property=properties[0]||''"><ui-option v-for="id in detail.deviceIds" :key="id" :value="id" :label="deviceName(id)"/></ui-select><ui-select v-model="property" placeholder="数值属性"><ui-option v-for="key in properties" :key="key" :value="key" :label="key"/></ui-select><ui-select v-model="clock"><ui-option value="event" label="设备事件时间"/><ui-option value="received" label="平台接收时间"/><ui-option value="available" label="首次可查询时间"/></ui-select></div><TimeSeriesChart :times="chart.times" :series="chart.series" :fill="false" :height="230" empty-text="当前固定样本没有可绘制的数值或时钟依据。"/><p class="lab-hint">曲线采用固定输入首 {{sample.length}} / {{total}} 条，{{chart.collapsedCount}} 个相同显示时刻仅在曲线合并。完整统计与事件分母采用全部固定输入；当前物模型、协议与单位不会补入历史资料。</p></div><div class="lab-card lab-stack"><h3>完整固定输入分页</h3><div class="lab-table-scroll"><ui-table :data="pageRows" empty-text="该页没有固定标准消息。"><ui-table-column label="设备 / 类型" min-width="180"><template #default="{row}">{{deviceName(row.message.deviceId)}}<p class="lab-meta">{{row.message.messageType}}</p></template></ui-table-column><ui-table-column label="事件 / 接收 / 可查询" min-width="230"><template #default="{row}">{{ruleLabTime(row.message.timestamp)}}<p class="lab-meta">接收 {{ruleLabTime(row.receivedAt)}}<br>可查询 {{ruleLabTime(row.availableAt)}}</p></template></ui-table-column><ui-table-column label="历史元数据" min-width="230"><template #default="{row}">{{row.protocolVersion || '协议版本未知'}} · {{row.configurationVersion || '配置版本未知'}}<p class="lab-meta">{{row.metadataQuality}} · 单位 {{JSON.stringify(row.units || {})}}</p></template></ui-table-column><ui-table-column label="操作" width="100"><template #default="{row}"><ui-button :data-lab-input="row.id" text size="small" @click="input=row;inputDialog=true">原值与依据</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="page" :page-size="20" :total="total" @current-change="page=$event;loadPage()"/></div></template></template>
 </section>
 <ui-dialog v-model="dialog" title="新建固定规则实验数据集" width="min(820px,94vw)" :close-on-click-modal="false" @close="dialog=false"><div class="lab-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="saving"><ui-form-item label="明确设备范围" required><ui-select v-model="form.deviceIds" multiple filterable :disabled="!!deviceId"><ui-option v-for="row in devices" :key="row.id" :value="row.id" :label="row.name || row.id"/></ui-select></ui-form-item><ui-form-item label="资料用途"><ui-select v-model="form.scope"><ui-option value="personal" label="个人实验输入"/><ui-option v-if="shareable" value="shared" label="受权共享输入"/></ui-select></ui-form-item><ui-form-item label="主评价区间" required><ui-date-range v-model="form.range" disable-future/></ui-form-item><ui-form-item label="预热起点" required><ui-date-time v-model="form.warmupStart"/></ui-form-item><div class="lab-grid"><ui-form-item label="历史排序依据"><ui-select v-model="form.timeBasis"><ui-option value="EVENT" label="设备事件时间排序"/><ui-option value="RECEIVED" label="平台接收时间排序"/></ui-select></ui-form-item><ui-form-item label="虚拟处理时钟"><ui-select v-model="form.clockPolicy"><ui-option v-for="[value,label] in Object.entries(clockPolicies)" :key="value" :value="value" :label="label"/></ui-select></ui-form-item><ui-form-item label="求值语义版本"><ui-select v-model="form.semanticsVersion"><ui-option v-for="[value,label] in Object.entries(semantics)" :key="value" :value="value" :label="label"/></ui-select></ui-form-item><ui-form-item label="窗口起点初态"><ui-select v-model="form.initialStatePolicy"><ui-option v-for="[value,label] in Object.entries(initialPolicies)" :key="value" :value="value" :label="label"/></ui-select></ui-form-item></div><p class="lab-hint">持续条件依赖后续匹配消息才检查持续时间。缺少完整 trace、阶段时钟或初态时，结果保留历史模拟与未知限制。</p></ui-form></div><template #footer><ui-button :disabled="saving" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="saving" @click="save">固定数据集</ui-button></template></ui-dialog>
 <ui-dialog v-model="inputDialog" title="固定标准消息与求值依据" width="min(900px,94vw)" @close="inputDialog=false"><div v-if="input" class="lab-dialog-body"><p class="lab-meta">标准消息 {{input.message.messageId}} · 输入哈希 {{input.hash}}</p><p>{{deviceName(input.message.deviceId)}} · {{input.message.messageType}}</p><p class="lab-meta">事件 {{ruleLabTime(input.message.timestamp)}}<br>接收 {{ruleLabTime(input.receivedAt)}} · 可查询 {{ruleLabTime(input.availableAt)}} · {{input.availableAtSource || '可查询来源未知'}}</p><p class="lab-meta">解析 {{input.message.parserVersion || '版本未知'}} · 协议 {{input.protocolVersion || '未知'}} · 点表 {{input.pointTableVersion || '未知'}} · 配置 {{input.configurationVersion || '未知'}}</p><div class="lab-table-scroll"><table class="lab-native-table"><tbody><tr v-for="[key,value] in Object.entries(input.message.properties || {})" :key="key"><th>{{key}}</th><td>{{typeof value==='object'?JSON.stringify(value):value}}</td><td>{{input.units?.[key] || '历史单位未知'}}</td></tr></tbody></table></div><p v-if="input.message.event" class="lab-hint">设备断言 {{JSON.stringify(input.message.event)}}</p><ui-button v-if="input.message.rawMessageId&&can('menu:raw')" size="small" @click="raw(input)">查看关联原文</ui-button><p class="lab-hint">原文当前可用性需由原文接口核实；固定输入与统计保留。</p><article v-for="trace in input.traces || []" :key="trace.id" class="lab-card"><strong>{{trace.status}} · {{qualityLabels[trace.reproductionQuality] || trace.reproductionQuality}}</strong><p class="lab-meta">{{semantics[trace.semanticsVersion] || trace.semanticsVersion}} · claim {{trace.claimToken}} · attempt {{trace.attempt}}<br>{{ruleLabTime(trace.startedAt)}} 至 {{ruleLabTime(trace.finishedAt)}}</p><p v-for="reason in trace.limitations || []" :key="reason" class="lab-hint">{{reasonText(reason)}}</p><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>实际规则版本</th><th>逐阶段处理时钟</th><th>判断 / 提交</th></tr></thead><tbody><tr v-for="step in trace.steps || []" :key="step.sequence+':'+step.ruleRevisionId"><td>{{step.ruleRevisionId}}</td><td>持续 {{step.times?.durationAtSeconds!=null?ruleLabTime(step.times.durationAtSeconds*1000):'未知'}}<br>触发 {{ruleLabTime(step.times?.raiseAtMillis)}}<br>恢复 {{ruleLabTime(step.times?.recoverAtMillis)}}</td><td>{{step.matched?'匹配':'未匹配'}} · {{step.durationSatisfied?'持续条件已满足':'持续条件未满足'}}<br>提交 {{ruleLabTime(step.committedAt)}}<br>{{step.evaluationError}}</td></tr></tbody></table></div></article><p v-if="!input.traces?.length" class="lab-hint">缺少该消息的实际求值 trace，不能将历史排序与时钟假设描述为精确生产重现。</p></div><template #footer><ui-button @click="inputDialog=false">关闭</ui-button></template></ui-dialog>

</template>
